const { withInfoPlist, withXcodeProject } = require('expo/config-plugins')

const deploymentTarget = '16.4'

/**
 * Keep the generated Xcode project and its Info.plist on the same release floor.
 * The source iOS project is generated by Expo, so this plugin is the checked-in
 * owner of IPHONEOS_DEPLOYMENT_TARGET rather than a generated pbxproj.
 */
module.exports = function withIosReleaseContract(config) {
  config = withInfoPlist(config, (next) => {
    next.modResults.MinimumOSVersion = deploymentTarget
    return next
  })

  return withXcodeProject(config, (next) => {
    for (const configuration of Object.values(next.modResults.pbxXCBuildConfigurationSection())) {
      if (typeof configuration !== 'object' || !configuration?.buildSettings) continue
      configuration.buildSettings.IPHONEOS_DEPLOYMENT_TARGET = deploymentTarget
      configuration.buildSettings.TARGETED_DEVICE_FAMILY = '1'
    }
    return next
  })
}
